							value={bankId}
							onChange={(e) => setBankId(e.target.value)}
							style={{ flex: 1 }}
						>
							<option value="">— 请选择 —</option>
							{banks.map((b) => (
								<option key={b.id} value={b.id}>
									{b.name}
								</option>
							))}
						</select>
						{bankId && (
							<button className="btn danger" onClick={removeBank}>
								删除题库
							</button>
						)}
					</div>
					{banks.length === 0 && (
						<p className="muted">还没有题库，先去「导入」页添加题目。</p>
					)}

					<label>练习范围</label>
					<div className="row">
						<select
							value={mode}
							onChange={(e) => setMode(e.target.value as PracticeMode)}
						>
							{(Object.keys(MODE_LABEL) as PracticeMode[]).map((m) => (
								<option key={m} value={m}>
									{MODE_LABEL[m]}
								</option>
							))}
						</select>
						{mode === "byType" && (
							<select
								value={qType}
								onChange={(e) => setQType(e.target.value as QuestionType)}
							>
								<option value="">选题型</option>
								<option value="single">单选</option>
								<option value="multiple">多选</option>
								<option value="boolean">判断</option>
							</select>
						)}
						{mode === "byTag" && (
							<input
								placeholder="知识点标签"
								value={tag}
								onChange={(e) => setTag(e.target.value)}
								style={{ flex: 1 }}
							/>
						)}
					</div>

					<label className="row" style={{ cursor: "pointer", marginTop: 12 }}>
						<input
							type="checkbox"
							checked={shuffle}
							onChange={(e) => setShuffle(e.target.checked)}
							style={{ width: "auto" }}
						/>
						<span>乱序练习</span>
					</label>

					<div className="row" style={{ marginTop: 16 }}>
						<button className="btn" onClick={start}>
							开始练习
						</button>
					</div>
				</div>
			)}

			{session && scorecard && (
				<Scorecard
					data={scorecard}
					onReviewWrong={() => onNavigateWrong?.()}
					onRestart={reset}
				/>
			)}

			{session && !scorecard && current && (
				<>
					<div className="row" style={{ marginBottom: 8 }}>
						<span className="muted">
							第 {idx + 1} / {questions.length} 题
						</span>
						<div className="spacer" />
						<button className="btn ghost" onClick={reset}>
							退出练习
						</button>
					</div>

					<QuestionNav
						total={questions.length}
						current={idx}
						gradedById={gradedById}
						questionIds={questions.map((q) => q.id)}
						onJump={jump}
					/>

					<QuestionCard
						key={current.id}
						question={current}
						graded={graded}
						onSubmit={onGrade}
					/>
					{graded && (
						<TutorPanel questionId={current.id} attemptId={graded.attemptId} />
					)}

					<div className="row" style={{ marginTop: 12 }}>
						<button
							className="btn ghost"
							onClick={() => jump(idx - 1)}
							disabled={idx === 0}
						>
							上一题
						</button>
						<span className="spacer" />
						{idx >= questions.length - 1 ? (
							<button className="btn" onClick={finish}>
								完成 · 看成绩单
							</button>
						) : (
							<button className="btn" onClick={() => jump(idx + 1)}>
								下一题
							</button>
						)}
					</div>
				</>
			)}
		</div>
	);
}

